:root {
  --bg: #2c1a0e;
  --surface: #3d2510;
  --accent: #e8742a;
  --accent-light: #f5a05a;
  --text-primary: #fdebd0;
  --text-muted: #b8865a;
  --divider: #5a3320;
  --badge-bg: #e8742a;
  --badge-text: #1a0a00;
}

.ticket {
  background-color: var(--bg);
  border: 2px solid var(--accent);
  border-radius: 16px;
  padding: 20px 24px;
  width: 340px;
  margin: 40px auto;
}

.ticket-header {
  display: flex;
  align-items: center;
  gap: 14px;
}

.ticket-icon {
  font-size: 36px;
  line-height: 1;
}

.ticket-title h1 {
  font-size: 18px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0 0 4px 0;
}

.ticket-subtitle {
  font-size: 12px;
  color: var(--text-muted);
  margin: 0;
}

.ticket-divider {
  display: flex;
  align-items: center;
  gap: 0;
  margin: 16px 0;
}

.divider-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--accent);
  flex-shrink: 0;
}

.divider-line {
  flex: 1;
  height: 1px;
  background-color: var(--divider);
  border-top: 2px dashed var(--divider);
}

.ticket-details {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
}

.detail-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.detail-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
}

.detail-value {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
}

.seat-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  padding: 3px 10px;
  border-radius: 20px;
  font-size: 13px;
}
